import{z as B,x as i,o as E,c as l,q as t,j as r,D as e,d as A,s as n,S as s}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"OAuth / OIDC 入口","description":"","frontmatter":{"title":"OAuth / OIDC 入口","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/oauth-oidc.md","filePath":"cs/oauth-oidc.md","lastUpdated":1791063341000}'),d={name:"cs/oauth-oidc.md"};function D(p,a,h,C,c,_){const o=i("Mermaid");return E(),l("div",null,[a[2]||(a[2]=t('<h1 id="oauth-oidc-入口" tabindex="-1">OAuth / OIDC 入口 <a class="header-anchor" href="#oauth-oidc-入口" aria-label="Permalink to &quot;OAuth / OIDC 入口&quot;">​</a></h1><div class="epigraph"><p>OAuth 让用户把对某 API 的有限访问委托给客户端，而不交出账号口令；OIDC 在其上加一层身份令牌。</p><footer>—— 据 RFC 6749 OAuth 2.0；OpenID Connect 核心；Anderson 对委托的整理</footer></div><p><a href="/cs/kerberos">上一课</a>用 KDC 票据做域内 SSO。本课不重画 TGT。缺口是开放互联网：第三方应用要读用户在另一服务上的数据，不能把用户口令交给第三方。OAuth 发访问令牌；OIDC 的 ID Token 回答「是谁」。访问控制矩阵下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Kerberos 假设共享的组织 KDC。Web 上身份提供者、资源服务器、客户端是不同主体。浏览器重定向完成用户同意。缺口是<strong>委托与认证分层</strong>：OAuth 本意是授权，OIDC 把认证声明做成 JWT 一类令牌。本课不把全部 grant 类型写成百科，只钉授权码直觉与令牌不是口令。</p><p><span class="marginnote">把访问令牌当万能 Cookie 会破坏最小特权。PKCE 约束公共客户端，是防御合同，不是攻击说明。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>授权码：客户端把用户送到 IdP，用户同意后客户端用码换令牌，资源服务器验令牌。OIDC：额外得到 ID Token，应用读身份声明。TLS 保护重定向与换票。本课不实现某家登录按钮。</p><p><span class="marginnote">术语翻译：ID Token 就是一张 IdP 签名的「身份卡片」（JWT），上面写着你是谁、卡片发给哪个应用、有效期到几点。客户端验签后读声明即可完成登录，不用再拿它去问资源服务器。</span></p>',9)),(E(),r(s,null,{default:e(()=>[n(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E7%94%A8%E6%88%B7%E5%90%8C%E6%84%8F%22%5D%20--%3E%20IDP%5B%22%E8%BA%AB%E4%BB%BD%E6%8F%90%E4%BE%9B%E8%80%85%22%5D%0A%20%20IDP%20--%3E%20AT%5B%22%E8%AE%BF%E9%97%AE%E4%BB%A4%E7%89%8C%22%5D%0A%20%20IDP%20--%3E%20ID%5B%22OIDC%20%E8%BA%AB%E4%BB%BD%E4%BB%A4%E7%89%8C%22%5D%0A%20%20AT%20--%3E%20API%5B%22%E8%B5%84%E6%BA%90%E6%9C%8D%E5%8A%A1%E5%99%A8%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>口令只进 IdP；客户端持有限范围令牌。这是<a href="/cs/acl-least-priv">最小特权</a> 在 Web 上的一种实现。令牌泄露的影响面是范围与期限，故要短寿命与绑定。后课 ACL 决定资源服务器内部谁能碰哪一行。</p><p><span class="marginnote">直觉类比：访问令牌像酒店房卡——只能开你被授权的那几扇门，退房即失效；口令则像你家的总钥匙。把房卡交给前台代办（委托）丢了损失有限，把总钥匙交出去就是灾难。</span></p><p><span class="marginnote">数字实例：访问令牌的寿命常设在 5 到 60 分钟量级，到期后客户端拿长效的 refresh token 去换新的。这样即使一枚访问令牌泄露，攻击窗口也只有几分钟，而不是账号被长期冒用。</span></p>',4)),(E(),r(s,null,{default:e(()=>[n(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20T1%5B%22%E8%AE%BF%E9%97%AE%E4%BB%A4%E7%89%8C%20%E5%9B%9E%E7%AD%94%20%E6%88%91%E8%83%BD%E5%81%9A%E4%BB%80%E4%B9%88%22%5D%20--%3E%20C1%5B%22%E8%B5%84%E6%BA%90%E6%9C%8D%E5%8A%A1%E5%99%A8%E9%AA%8C%E8%8C%83%E5%9B%B4%E4%B8%8E%E6%9C%9F%E9%99%90%22%5D%0A%20%20T2%5B%22ID%20Token%20%E5%9B%9E%E7%AD%94%20%E6%88%91%E6%98%AF%E8%B0%81%22%5D%20--%3E%20C2%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%E9%AA%8C%E7%AD%BE%E5%90%8D%E8%AF%BB%E5%A3%B0%E6%98%8E%22%5D%0A%20%20T1%20-.%20%E6%B3%84%E9%9C%B2%20.-%3E%20R1%5B%22%E6%8D%9F%E5%A4%B1%E9%9D%A2%20%E8%8C%83%E5%9B%B4%C3%97%E5%89%A9%E4%BD%99%E5%AF%BF%E5%91%BD%22%5D%0A%20%20T2%20-.%20%E6%B3%84%E9%9C%B2%20.-%3E%20R2%5B%22%E6%8D%9F%E5%A4%B1%E9%9D%A2%20%E8%BA%AB%E4%BB%BD%E5%A3%B0%E6%98%8E%E6%9A%B4%E9%9C%B2%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 SAML 插成第二条主干。登录成功之后对象上的权限如何表示，下一课访问控制。</p><p>后课默认：Web 委托用令牌。客体上的允许集合是保护矩阵。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>OAuth 委托访问；OIDC 附加身份声明。</li><li>第三方不应拿到用户长期口令。</li><li>访问控制下一课。</li><li>出处：RFC 6749；OpenID Connect；Anderson。</li></ul>',5))])}const m=B(d,[["render",D]]);export{T as __pageData,m as default};
